function multiplicar(a, b) {
  return a * b;
}

function calcularArea(largura, altura) {
  return multiplicar(largura, altura);
}

console.log('Inicio do script');
const area = calcularArea(4, 5);
console.log(`Area: ${area}`);
console.log('Fim do script');

// Ordem na call stack:
// 1. Entra calcularArea(4, 5)
// 2. Entra multiplicar(4, 5)
// 3. Sai multiplicar, devolve 20
// 4. Sai calcularArea, devolve 20
// A stack fica sempre vazia entre cada linha sincrona do topo do script.

console.log('A');

setTimeout(() => {
  console.log('C (callback do setTimeout)');
}, 0);

console.log('B');

// Saida: A, B, C
// setTimeout apenas agenda a callback e devolve o controlo de imediato;
// nao bloqueia nem espera pelo temporizador.

setTimeout(() => console.log('primeiro macrotask'), 0);
setTimeout(() => console.log('segundo macrotask'), 0);
console.log('codigo sincrono');

// Saida: codigo sincrono, primeiro macrotask, segundo macrotask
// Ambos os setTimeout tem o mesmo atraso, por isso correm pela ordem
// em que foram agendados (FIFO).

console.log('1');

Promise.resolve().then(() => console.log('3 (microtask)'));

console.log('2');

// Saida: 1, 2, 3
// A callback do then so corre depois de todo o codigo sincrono terminar,
// mas antes de qualquer macrotask.

console.log('1: sincrono');

setTimeout(() => {
  console.log('4: macrotask (setTimeout)');
}, 0);

Promise.resolve().then(() => {
  console.log('3: microtask (promise)');
});

console.log('2: sincrono');

// Saida: 1, 2, 3, 4

// Pseudocodigo (sintaxe JS) do algoritmo do event loop, simplificado:
function eventLoop() {
  while (true) {
    if (callStack.estaVazia()) {
      while (!filaDeMicrotasks.estaVazia()) {
        const microtask = filaDeMicrotasks.retirarPrimeira();
        callStack.executar(microtask);
      }

      if (!filaDeMacrotasks.estaVazia()) {
        const macrotask = filaDeMacrotasks.retirarPrimeira();
        callStack.executar(macrotask);
      }
    }
  }
}

// callStack e as filas nao existem como objetos acessiveis ao programador;
// isto e apenas um modelo para raciocinar sobre a ordem de execucao.

exercises.statement:
Considera o código seguinte:

console.log('1');
setTimeout(() => console.log('2'), 0);
console.log('3');
Promise.resolve().then(() => console.log('4'));
console.log('5');

Sem executar o código, escreve por escrito qual vai ser a ordem exata em que os números aparecem na consola, e explica numa frase porque é que o valor agendado pelo setTimeout aparece por último, apesar de estar escrito antes da Promise no código.

exercises.solution_code:
console.log('1');

setTimeout(() => console.log('2'), 0);

console.log('3');

Promise.resolve().then(() => console.log('4'));

console.log('5');

// Ordem real na consola: 1, 3, 5, 4, 2
// 1, 3 e 5 sao sincronos e correm de imediato, pela ordem em que aparecem no codigo.
// 4 e uma microtask (callback de uma Promise): corre assim que a call stack
// fica vazia, antes de qualquer macrotask.
// 2 e uma macrotask (callback do setTimeout): so corre depois de a fila
// de microtasks estar completamente vazia.

function demonstrarPrioridade() {
  console.log('inicio');

  setTimeout(() => {
    console.log('macrotask');
  }, 0);

  Promise.resolve().then(() => {
    console.log('microtask-a');
  });

  queueMicrotask(() => {
    console.log('microtask-b');
  });
}

demonstrarPrioridade();

// Saida: inicio, microtask-a, microtask-b, macrotask

exercises.statement:
Considera o código seguinte:

console.log('A');

Promise.resolve()
  .then(() => {
    console.log('B');
    return Promise.resolve();
  })
  .then(() => {
    console.log('C');
  });

setTimeout(() => {
  console.log('D');
}, 0);

console.log('E');

Escreve a ordem exata em que 'A', 'B', 'C', 'D' e 'E' vão aparecer na consola, e explica porque é que 'C' consegue aparecer antes de 'D', apesar de 'C' depender de uma segunda Promise que só é criada depois de 'B' já ter corrido.

exercises.solution_code:
console.log('A');

Promise.resolve()
  .then(() => {
    console.log('B');
    return Promise.resolve();
  })
  .then(() => {
    console.log('C');
  });

setTimeout(() => {
  console.log('D');
}, 0);

console.log('E');

// Ordem real: A, E, B, C, D

exercises.statement:
O código seguinte tenta contar quantas vezes uma tarefa se repete e, ao fim de cerca de 100 milissegundos, mostrar esse total através de um setTimeout. Na prática, a mensagem do setTimeout nunca chega a aparecer:

let contador = 0;

function repetir() {
  contador++;
  Promise.resolve().then(repetir);
}

repetir();

setTimeout(() => {
  console.log('Total de repeticoes:', contador);
}, 100);

Explica, em termos do event loop, porque é que o setTimeout nunca chega a executar, e reescreve o código de forma que o contador continue a aumentar indefinidamente, mas o setTimeout consiga mesmo assim executar ao fim de cerca de 100 milissegundos, mostrando o valor do contador nesse momento.

exercises.solution_code:
let contador = 0;
const LIMITE_DE_REPETICOES = 20000;

function repetir() {
  contador++;
  if (contador >= LIMITE_DE_REPETICOES) {
    return; // condicao de paragem: sem ela o programa nunca termina
  }

  if (contador % 1000 === 0) {
    // A cada 1000 chamadas, agenda a continuacao como macrotask,
    // devolvendo o controlo ao event loop.
    setTimeout(repetir, 0);
  } else {
    Promise.resolve().then(repetir);
  }
}

repetir();

setTimeout(() => {
  console.log('Total de repeticoes ao fim de ~100ms:', contador);
}, 100);
